-- Row-level security for every business-owned table + Account.sessionVersion (session invalidation on password change).
-- Runtime role: the application switches to it transaction-locally (src/lib/db-rls.ts) whenever a business context is active.
-- The connection owner keeps full access for login, webhook routing, cron enumeration and migrations.

ALTER TABLE "accounts" ADD COLUMN "session_version" INTEGER NOT NULL DEFAULT 0;

DO $$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'ultracrm_runtime') THEN CREATE ROLE ultracrm_runtime NOLOGIN NOBYPASSRLS NOINHERIT; END IF; END $$;
GRANT ultracrm_runtime TO CURRENT_USER;
GRANT USAGE ON SCHEMA public TO ultracrm_runtime;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO ultracrm_runtime;
GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA public TO ultracrm_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO ultracrm_runtime;
ALTER DEFAULT PRIVILEGES IN SCHEMA public GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO ultracrm_runtime;

ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "users";
-- users: the signed-in account may read its own memberships in other businesses (business switcher); writes stay tenant-bound.
CREATE POLICY tenant_isolation ON "users" TO ultracrm_runtime USING ("business_id" = current_setting('app.business_id', true) OR "account_id" = current_setting('app.account_id', true)) WITH CHECK ("business_id" = current_setting('app.business_id', true));
