-- Child tables without business_id: visible/writable only through a parent row of the current business.
ALTER TABLE "campaign_recipients" ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS tenant_isolation ON "campaign_recipients";
CREATE POLICY tenant_isolation ON "campaign_recipients" TO ultracrm_runtime USING (EXISTS (SELECT 1 FROM "campaigns" p WHERE p."id" = "campaign_recipients"."campaign_id" AND p."business_id" = current_setting('app.business_id', true))) WITH CHECK (EXISTS (SELECT 1 FROM "campaigns" p WHERE p."id" = "campaign_recipients"."campaign_id" AND p."business_id" = current_setting('app.business_id', true)));
